package com.preyansh.ridesharing.dto;

import com.preyansh.ridesharing.model.VehicleType;

// DTO (Data Transfer Object) that defines the vehicle data returned by the API.
// It separates the API response structure from the database entity.
public class VehicleResponse {

    // Unique ID generated by the database for the vehicle.
    private Long id;

    // Vehicle's registration number, such as "MH12AB1234".
    private String registrationNumber;

    // Vehicle's model name, such as "Swift".
    private String model;

    // Vehicle category, such as HATCHBACK, SEDAN, SUV, or MUV.
    private VehicleType vehicleType;

    // No-argument constructor.
    // Useful for frameworks or code that needs to create an empty DTO.
    public VehicleResponse() {
    }

    // Parameterized constructor that initializes all response fields at once.
    // The service can use this to convert a Vehicle entity into a VehicleResponse.
    public VehicleResponse(Long id, String registrationNumber, String model, VehicleType vehicleType) {
        // Store the database-generated vehicle ID.
        this.id = id;
        // Store the vehicle's registration number.
        this.registrationNumber = registrationNumber;
        // Store the vehicle's model name.
        this.model = model;
        // Store the vehicle's category.
        this.vehicleType = vehicleType;
    }

    // Returns the vehicle ID for serialization in the API response.
    public Long getId() {
        return id;
    }

    // Returns the vehicle's registration number.
    public String getRegistrationNumber() {
        return registrationNumber;
    }

    // Returns the vehicle's model name.
    public String getModel() {
        return model;
    }

    // Returns the vehicle's category.
    public VehicleType getVehicleType() {
        return vehicleType;
    }
}